// Extrae el array de turnos del body y prepara un item por cada uno
const body = $input.first().json.body;
const turnos = body.turnos || [];
const centroNombre = body.centro_nombre || 'el centro';
const centroDireccion = body.centro_direccion || '';

// Normaliza un celular argentino al formato +549XXXXXXXXXX requerido por YCloud
function normalizarCelular(raw) {
  // Quitar todo lo que no sea dígito
  let n = String(raw).replace(/\D/g, '');
  // Quitar 0 inicial (ej: 03624... → 3624...)
  if (n.startsWith('0')) n = n.slice(1);
  // Si ya empieza con 549 → ok
  if (n.startsWith('549')) return '+' + n;
  // Si empieza con 54 pero sin el 9 móvil → insertar 9
  if (n.startsWith('54')) return '+549' + n.slice(2);
  // Si son 10 dígitos (ej: 3624075957) o 11 dígitos empezando en 9 (ej: 93624075957)
  if (n.length === 11 && n.startsWith('9')) return '+54' + n;
  if (n.length === 10) return '+549' + n;
  // Fallback: solo agregar +549
  return '+549' + n;
}

return turnos.map(t => ({
  json: {
    turno_id:     t.turno_id,
    to:           normalizarCelular(t.celular),
    nombre:       t.paciente_nombre,
    dia:          t.fecha.split('-').reverse().join('/'),
    hora:         t.hora.substring(0, 5),
    servicio:     t.servicio || '',
    profesional:  t.profesional || '',
    centro_nombre: centroNombre,
    direccion:    centroDireccion
  }
}));
